// generated by gemini-3.5-flash-lite for PR #5855 (round 0): many_keys_parsing
// intent: Verify object parsing with a large number of keys to stress container insertion and key moving.
#include <nlohmann/json.hpp>
#include <sstream>
#include <iostream>

int main() {
    try {
        std::ostringstream oss;
        oss << "{";
        for (int i = 0; i < 50; ++i) {
            if (i > 0) oss << ",";
            oss << "\"key_number_" << i << "\": " << i;
        }
        oss << "}";
        auto j = nlohmann::json::parse(oss.str());
        std::cout << j.size() << "\n";
        std::cout << j["key_number_25"] << "\n";
    } catch (const std::exception& e) {
        std::cout << "EXCEPTION:" << e.what() << "\n";
    }
    return 0;
}
